    /* 专辑封面 */
    .ios-music-widget .music-album {
      width: 142px;
      height: 142px;
      flex-shrink: 0;
      border-radius: 10px;
      overflow: hidden;
      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
