    }

    .ios-music-widget .music-title {
      font-size: 20px;
      font-weight: 600;
      color: #fff;
      letter-spacing: -0.3px;
      margin-bottom: 2px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .ios-music-widget .music-artist {
      font-size: 14px;
      font-weight: 400;
      color: rgba(255, 255, 255, 0.6);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    /* 控制按钮 */
    .ios-music-widget .music-controls {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 24px;
    }

    .ios-music-widget .music-btn {
      background: none;
      border: none;
      cursor: pointer;
      padding: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: rgba(255, 255, 255, 0.9);
      transition: transform 0.1s ease, opacity 0.1s ease;
      -webkit-tap-highlight-color: transparent;
    }

    .ios-music-widget .music-btn:active {
      transform: scale(0.9);
      opacity: 0.6;
    }

    .ios-music-widget .music-btn.skip-btn svg {
      width: 36px;
      height: 36px;
      fill: currentColor;
    }

    .ios-music-widget .music-btn.play-btn svg {
      width: 48px;
      height: 48px;
      fill: currentColor;
    }

    /* 进度条区域 */
    .ios-music-widget .music-progress {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .ios-music-widget .progress-track {
      flex: 1;
      height: 5px;
      background: rgba(255, 255, 255, 0.3);
      border-radius: 2.5px;
      cursor: pointer;
      position: relative;
      overflow: hidden;
    }

    .ios-music-widget .progress-fill {
      position: absolute;
      left: 0;
      top: 0;
      height: 100%;
      background: rgba(255, 255, 255, 0.85);
      border-radius: 2.5px;
      transition: width 0.15s linear;
    }

    .ios-music-widget .music-time {
      font-size: 11px;
      font-weight: 500;
      color: rgba(255, 255, 255, 0.55);
      font-variant-numeric: tabular-nums;
      min-width: 32px;
    }

    .ios-music-widget .music-time.current {
      text-align: right;
    }

    .ios-music-widget .music-time.total {
      text-align: left;
    }

    /* 专辑封面编辑提示 */
    .ios-music-widget .music-album {
      cursor: pointer;
    }

    .ios-music-widget .music-album-edit-hint {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity 0.2s ease;
      border-radius: 10px;
    }

    .ios-music-widget .music-album-edit-hint svg {
      width: 32px;
      height: 32px;
      stroke: #fff;
      stroke-width: 2;
      fill: none;
    }

    .ios-music-widget .music-album:hover .music-album-edit-hint,
    .ios-music-widget .music-album:active .music-album-edit-hint {
      opacity: 1;
    }

    /* 歌曲名/歌手名可编辑样式 */
    .ios-music-widget .music-title,
    .ios-music-widget .music-artist {
      cursor: pointer;
      transition: background 0.15s ease;
      border-radius: 4px;
      padding: 2px 6px;
      margin: -2px -6px;
    }

    .ios-music-widget .music-title:hover,
    .ios-music-widget .music-artist:hover {
      background: rgba(255, 255, 255, 0.1);
    }

    .ios-music-widget .music-title:active,
    .ios-music-widget .music-artist:active {
      background: rgba(255, 255, 255, 0.15);
    }

    /* ========== 组件选择器 - INS风格重设计 ========== */

    /* 遮罩层 - 毛玻璃效果 */
    .widget-picker-overlay {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.4);
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
      z-index: 20000;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.35s cubic-bezier(0.4, 0, 0.2, 1);
      display: flex;
      align-items: flex-end;
      justify-content: center;
    }

    .widget-picker-overlay.active {
      opacity: 1;
      pointer-events: auto;
    }

    /* 主面板 - 异形设计 */
    .widget-picker-sheet {
      width: 100%;
      max-width: 400px;
      max-height: 75vh;
      background: var(--bg-primary);
      border-radius: 28px 28px 0 0;
      padding: 0;
      transform: translateY(100%);
      transition: transform 0.4s cubic-bezier(0.32, 0.72, 0, 1);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.15);
      position: relative;
    }

    /* 装饰星星 */
    .widget-picker-sheet::before {
      content: '✦';
      position: absolute;
      top: 16px;
      right: 60px;
      font-size: 10px;
      color: var(--text-tertiary);
      opacity: 0.5;
      animation: starTwinkle 2s ease-in-out infinite;
    }

    .widget-picker-sheet::after {
      content: '✧';
      position: absolute;
      top: 24px;
      right: 45px;
      font-size: 8px;
      color: var(--text-tertiary);
      opacity: 0.3;
      animation: starTwinkle 2s ease-in-out infinite 0.5s;
    }

    @keyframes starTwinkle {
      0%, 100% { opacity: 0.3; transform: scale(1); }
      50% { opacity: 0.7; transform: scale(1.2); }
    }

    .widget-picker-overlay.active .widget-picker-sheet {
      transform: translateY(0);
    }

    /* 顶部拖拽手柄 - 像素风格 */
    .widget-picker-handle {
      width: 40px;
      height: 4px;
      background: var(--text-tertiary);
      border-radius: 2px;
      margin: 14px auto 6px;
      position: relative;
