    }

    .desktop-presets-row::-webkit-scrollbar {
      width: 0;
      height: 0;
    }

    .desktop-presets-row::-webkit-scrollbar-track {
      background: transparent;
    }

    .desktop-presets-row::-webkit-scrollbar-thumb {
      background: transparent;
      border-radius: 2px;
    }

    .desktop-preset-card {
      position: relative;
