    .tv-video-title {
      font-size: 13px;
      font-weight: 600;
      margin-bottom: 4px;
      color: var(--text-primary);
    }

    .tv-video-meta {
      font-size: 11px;
      color: var(--text-tertiary);
      font-family: 'JetBrains Mono', monospace;
    }

    /* Settings App Styles */
    .settings-header-section {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 28px;
      animation: slideDown 0.6s ease;
    }

    .settings-logo-area {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .settings-logo-icon {
      width: 40px;
      height: 40px;
      background: var(--accent-color);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--bg-primary);
    }

    .settings-logo-icon svg {
      width: 20px;
      height: 20px;
      stroke: var(--bg-primary);
      fill: none;
      stroke-width: 2;
    }

    .settings-logo-text {
      font-size: 18px;
      font-weight: 600;
      letter-spacing: -0.02em;
    }

    .settings-header-actions {
      display: flex;
      gap: 8px;
    }

    .settings-icon-btn {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .settings-icon-btn:hover {
      background: var(--hover-bg);
      transform: scale(1.05);
    }

    .settings-icon-btn svg {
      width: 16px;
      height: 16px;
      stroke: var(--text-primary);
      fill: none;
      stroke-width: 2;
    }


    /* ==================== 多开聊天框样式 V2 - INS简约风 ==================== */

    /* 聊天框卡片 */
    .chat-session-card-v2 {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 16px;
      background: var(--bg-secondary);
      border: 1.5px solid var(--border-color);
      border-radius: 12px;
      cursor: pointer;
      transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
      position: relative;
      overflow: hidden;
    }

    .chat-session-card-v2::before {
      content: '';
      position: absolute;
      left: 0;
      top: 0;
      width: 3px;
      height: 100%;
      background: transparent;
      transition: all 0.25s ease;
    }

    .chat-session-card-v2:hover {
      border-color: var(--text-tertiary);
      transform: translateX(2px);
    }

    .chat-session-card-v2.active {
      background: var(--bg-primary);
      border-color: var(--text-primary);
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    }

    .chat-session-card-v2.active::before {
      background: var(--text-primary);
    }

    /* 左侧内容区 */
    .chat-session-left {
      display: flex;
      align-items: center;
      gap: 12px;
      flex: 1;
      min-width: 0;
    }

    /* 图标 */
    .chat-session-icon-v2 {
      width: 36px;
      height: 36px;
      display: flex;
      align-items: center;
      justify-content: center;
      background: var(--bg-tertiary);
      border-radius: 10px;
      flex-shrink: 0;
      transition: all 0.2s ease;
    }

    .chat-session-icon-v2 svg {
      width: 18px;
      height: 18px;
      stroke: var(--text-secondary);
      fill: none;
      stroke-width: 2;
      transition: stroke 0.2s ease;
    }

    .chat-session-card-v2:hover .chat-session-icon-v2 {
      background: var(--bg-primary);
    }

    .chat-session-card-v2:hover .chat-session-icon-v2 svg {
      stroke: var(--text-primary);
    }

    .chat-session-card-v2.active .chat-session-icon-v2 {
      background: var(--bg-secondary);
    }

    .chat-session-card-v2.active .chat-session-icon-v2 svg {
      stroke: var(--text-primary);
    }

    /* 信息区 */
    .chat-session-info-v2 {
      flex: 1;
      min-width: 0;
    }

    .chat-session-name-v2 {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-primary);
      margin-bottom: 2px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .chat-session-meta-v2 {
      font-size: 11px;
      color: var(--text-tertiary);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    /* 操作按钮容器 */
    .chat-session-actions-v2 {
      display: flex;
      align-items: center;
      gap: 6px;
      flex-shrink: 0;
    }

    /* 操作按钮图标 */
    .session-action-icon {
      width: 36px;
      height: 36px;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
      border: none;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.2s ease;
      padding: 0;
      position: relative;
    }

    .session-action-icon svg {
      width: 16px;
      height: 16px;
      stroke: var(--text-tertiary);
      fill: none;
      stroke-width: 2;
      transition: all 0.2s ease;
    }

    .session-action-icon:hover {
      background: var(--bg-tertiary);
    }

    .session-action-icon:hover svg {
      stroke: var(--text-secondary);
    }

    .session-action-icon:active {
      transform: scale(0.95);
    }

    /* 同步按钮特殊样式 */
    .session-action-icon[data-synced="false"] .sync-icon {
      fill: none;
      stroke: var(--text-tertiary);
    }

    .session-action-icon[data-synced="true"] .sync-icon {
      fill: var(--text-primary);
      stroke: var(--text-primary);
    }

    .session-action-icon[data-synced="false"]:hover .sync-icon {
      stroke: var(--text-secondary);
      fill: none;
    }

    .session-action-icon[data-synced="true"]:hover {
      background: var(--bg-secondary);
    }

    .session-action-icon[data-synced="true"]:hover .sync-icon {
      fill: var(--text-primary);
      stroke: var(--text-primary);
    }

    /* 删除按钮 */
    .session-action-icon.delete svg {
      stroke: var(--text-tertiary);
    }

    .session-action-icon.delete:hover {
      background: rgba(239, 68, 68, 0.1);
    }

    .session-action-icon.delete:hover svg {
      stroke: #ef4444;
    }

    /* Dark主题优化 */
    [data-theme='dark'] .chat-session-card-v2 {
      background: #151515;
      border-color: #2a2a2a;
    }

    [data-theme='dark'] .chat-session-card-v2:hover {
      border-color: #404040;
    }

    [data-theme='dark'] .chat-session-card-v2.active {
      background: #141414;
      border-color: #505050;
      box-shadow: 0 2px 12px rgba(0, 0, 0, 0.3);
    }

    [data-theme='dark'] .chat-session-icon-v2 {
      background: #1f1f1f;
    }

    [data-theme='dark'] .chat-session-card-v2:hover .chat-session-icon-v2 {
      background: #252525;
    }

    [data-theme='dark'] .chat-session-card-v2.active .chat-session-icon-v2 {
      background: #202020;
    }

    [data-theme='dark'] .session-action-icon:hover {
      background: #202020;
    }

    /* Light主题优化 */
    [data-theme='light'] .chat-session-card-v2 {
      background: #ffffff;
      border-color: #e5e5e5;
    }

    [data-theme='light'] .chat-session-card-v2:hover {
      border-color: #d4d4d4;
    }

    [data-theme='light'] .chat-session-card-v2.active {
      background: #fafafa;
      border-color: #a3a3a3;
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
    }

    [data-theme='light'] .chat-session-icon-v2 {
      background: #fafafa;
    }

    [data-theme='light'] .chat-session-card-v2:hover .chat-session-icon-v2 {
      background: #ffffff;
    }

    [data-theme='light'] .chat-session-card-v2.active .chat-session-icon-v2 {
      background: #f5f5f5;
    }

    [data-theme='light'] .session-action-icon:hover {
      background: #fafafa;
    }

    /* ==================== 多开聊天框样式结束 ==================== */

    .settings-section {
      margin-bottom: 28px;
    }

    .settings-section-header {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--text-secondary);
      margin-bottom: 12px;
      padding-left: 4px;
      position: relative;
    }

    .settings-section-header::before {
      content: '';
      position: absolute;
      left: -12px;
      top: 50%;
      transform: translateY(-50%);
      width: 4px;
      height: 4px;
      background: var(--accent-color);
      border-radius: 50%;
    }

    .settings-card {
      background: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      border-radius: 16px;
      padding: 20px;
      margin-bottom: 12px;
      transition: all 0.2s ease;
      position: relative;
      overflow: hidden;
    }

    .settings-card::before {
      content: '';
      position: absolute;
      top: 0;
      right: 0;
      width: 60px;
      height: 60px;
      background: linear-gradient(135deg, transparent, var(--accent-color));
      opacity: 0.02;
      border-radius: 0 16px 0 100%;
    }

    .settings-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-sm);
    }

    /* ==================== Chat Token UI ==================== */
    .token-card {
      padding: 22px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .token-summary {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .token-summary-text {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .token-title {
      font-size: 11px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-tertiary);
    }

    .token-value {
      font-size: 28px;
      font-weight: 600;
      color: var(--text-primary);
      font-family: 'JetBrains Mono', monospace;
      line-height: 1;
    }

    .token-unit {
      font-size: 10px;
      letter-spacing: 0.24em;
      color: var(--text-tertiary);
    }

    .token-orbit {
      width: 46px;
      height: 46px;
      border-radius: 50%;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .token-orbit-ring {
      position: absolute;
      inset: 4px;
      border-radius: 50%;
      border: 1px dashed var(--text-tertiary);
      opacity: 0.4;
      animation: tokenOrbitSpin 12s linear infinite;
    }

    .token-orbit-core {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--text-primary);
      box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.04);
    }

    @keyframes tokenOrbitSpin {
      0% { transform: rotate(0deg); }
      100% { transform: rotate(360deg); }
    }

    .token-breakdown {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .token-row {
      display: grid;
      grid-template-columns: 72px 1fr auto;
      gap: 10px;
      align-items: center;
    }

    .token-label {
      font-size: 12px;
      color: var(--text-secondary);
    }

    .token-bar {
      height: 6px;
      border-radius: 999px;
      background: var(--bg-primary);
      border: 1px solid var(--border-color);
      overflow: hidden;
      position: relative;
    }

    .token-bar-fill {
      display: block;
      height: 100%;
      background: var(--text-primary);
      transition: width 0.3s ease;
    }

