    /* ==================== Chat Data Cleaner ==================== */
    .chat-data-cleaner-overlay {
      position: absolute;
      inset: 0;
      z-index: 1500;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 18px;
      background: rgba(0, 0, 0, 0.25);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.25s ease;
    }

    [data-theme='dark'] .chat-data-cleaner-overlay {
      background: rgba(0, 0, 0, 0.45);
    }

    .chat-data-cleaner-overlay.active {
      opacity: 1;
      pointer-events: auto;
    }

    .chat-data-cleaner-card {
      position: relative;
      width: 100%;
      max-width: 360px;
      background: var(--bg-primary);
      border: 1px solid var(--border-color);
      border-radius: 22px;
      padding: 18px;
      box-shadow: var(--shadow-lg);
      transform: translateY(8px) scale(0.98);
      transition: transform 0.25s ease;
      overflow: hidden;
    }

    .chat-data-cleaner-overlay.active .chat-data-cleaner-card {
      transform: translateY(0) scale(1);
    }

    .chat-data-cleaner-stars {
      position: absolute;
      top: 12px;
      right: 14px;
      display: grid;
      gap: 6px;
      opacity: 0.25;
      pointer-events: none;
    }

    .chat-data-cleaner-stars span {
      width: 8px;
      height: 8px;
      background: var(--text-primary);
      clip-path: polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
    }

    .chat-data-cleaner-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 6px;
    }

    .chat-data-cleaner-title {
      font-size: 15px;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: var(--text-primary);
    }

    .chat-data-cleaner-close {
      width: 28px;
      height: 28px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
      background: var(--bg-secondary);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      padding: 0;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    .chat-data-cleaner-close svg {
      width: 14px;
      height: 14px;
      stroke: var(--text-secondary);
      fill: none;
      stroke-width: 2;
    }

    .chat-data-cleaner-close:hover {
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }

    .chat-data-cleaner-sub {
      font-size: 11px;
      color: var(--text-tertiary);
      margin-bottom: 12px;
    }

    .chat-data-cleaner-select-all {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 12px;
      border-radius: 12px;
      border: 1px dashed var(--border-color);
      background: var(--bg-secondary);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    .chat-data-cleaner-select-all:hover {
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }

    .chat-data-cleaner-select-label {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-primary);
      letter-spacing: 0.4px;
    }

    .chat-data-cleaner-select-meta {
      margin-left: auto;
      font-size: 10px;
      letter-spacing: 0.6px;
      text-transform: uppercase;
      color: var(--text-tertiary);
    }

    .chat-data-cleaner-list {
      display: grid;
      gap: 10px;
      margin-top: 12px;
    }

    .chat-data-cleaner-item {
      display: flex;
      align-items: center;
      gap: 12px;
      width: 100%;
      padding: 12px;
      border-radius: 14px;
      border: 1px solid var(--border-color);
      background: var(--bg-secondary);
      cursor: pointer;
      text-align: left;
      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
    }

    .chat-data-cleaner-item:hover {
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }

    .chat-data-cleaner-item.is-empty {
      opacity: 0.5;
      cursor: default;
    }

    .chat-data-cleaner-check {
      width: 18px;
      height: 18px;
      border-radius: 6px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      position: relative;
      flex-shrink: 0;
      transition: border-color 0.2s ease, background 0.2s ease;
    }

    .chat-data-cleaner-item.is-selected .chat-data-cleaner-check,
    .chat-data-cleaner-select-all.is-selected .chat-data-cleaner-check {
      background: var(--text-primary);
      border-color: var(--text-primary);
    }

    .chat-data-cleaner-item.is-selected .chat-data-cleaner-check::after,
    .chat-data-cleaner-select-all.is-selected .chat-data-cleaner-check::after {
      content: '';
      position: absolute;
      width: 6px;
      height: 10px;
      border: 2px solid var(--bg-primary);
      border-top: 0;
      border-left: 0;
      transform: translate(-50%, -55%) rotate(45deg);
      top: 50%;
      left: 50%;
    }

    .chat-data-cleaner-info {
      display: flex;
      flex-direction: column;
      gap: 4px;
      min-width: 0;
    }

    .chat-data-cleaner-label {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-primary);
    }

    .chat-data-cleaner-meta {
      font-size: 10px;
      color: var(--text-tertiary);
      letter-spacing: 0.4px;
      text-transform: uppercase;
    }

    .chat-data-cleaner-note {
      margin-top: 12px;
      padding: 10px 12px;
      border-radius: 12px;
      background: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      font-size: 10px;
      color: var(--text-tertiary);
      letter-spacing: 0.4px;
    }

    .chat-data-cleaner-actions {
      margin-top: 14px;
