      background: var(--accent-color);
      border-color: var(--accent-color);
    }

    .create-icon svg {
      width: 24px;
      height: 24px;
      stroke: var(--text-primary);
      fill: none;
      stroke-width: 2;
    }

    .create-card:hover .create-icon svg {
      stroke: var(--bg-primary);
    }

    .create-text {
      font-size: 12px;
      font-weight: 500;
      color: var(--text-secondary);
