      stroke-width: 2;
    }

    .character-circle-manage-block {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .character-circle-manage-title {
      font-size: 11px;
      color: var(--text-tertiary);
      letter-spacing: 0.02em;
    }

    .character-circle-multi-toolbar {
      display: flex;
      gap: 8px;
      justify-content: flex-end;
    }

    .character-circle-mini-btn {
      height: 26px;
      padding: 0 10px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
      background: var(--bg-secondary);
      color: var(--text-primary);
      font-size: 11px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .character-circle-mini-btn:hover {
      background: var(--hover-bg);
    }

    .character-circle-multi-list {
      max-height: 180px;
      overflow-y: auto;
      border-radius: 12px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      padding: 8px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      scrollbar-width: none;
    }

    .character-circle-multi-list::-webkit-scrollbar {
      display: none;
    }

    .character-circle-multi-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 6px 8px;
      border-radius: 10px;
      background: var(--bg-secondary);
      border: 1px solid var(--border-color);
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .character-circle-multi-item:hover {
      background: var(--hover-bg);
    }

    .character-circle-multi-item input {
      width: 14px;
      height: 14px;
      accent-color: var(--text-primary);
    }

    .character-circle-multi-name {
      font-size: 12px;
      color: var(--text-primary);
      font-weight: 600;
    }

    .character-circle-panel {
      background: var(--bg-secondary);
      border: 1px solid var(--border-color);
      border-radius: 16px;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .character-circle-panel-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
    }

    .character-circle-panel-title {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-primary);
      letter-spacing: -0.01em;
    }

    .character-circle-panel-subtitle {
      font-size: 11px;
      color: var(--text-tertiary);
      margin-top: 2px;
    }

    .character-circle-panel-body {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .character-circle-field {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .character-circle-label {
      font-size: 11px;
      color: var(--text-tertiary);
    }

    .character-circle-relation-hint {
      font-size: 11px;
      color: var(--text-secondary);
      line-height: 1.5;
      padding: 6px 10px;
      border-radius: 10px;
      border: 1px dashed var(--border-color);
      background: rgba(0, 0, 0, 0.04);
    }

    [data-theme='dark'] .character-circle-relation-hint {
      background: rgba(255, 255, 255, 0.04);
    }

    .character-circle-input {
      width: 100%;
      padding: 8px 10px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      color: var(--text-primary);
      font-size: 12px;
      outline: none;
      transition: border-color 0.2s ease;
    }

    .character-circle-input:focus {
      border-color: var(--text-secondary);
    }

    .character-circle-action-btn {
      height: 30px;
      padding: 0 12px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      color: var(--text-primary);
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s ease;
      white-space: nowrap;
    }

    .character-circle-action-btn:hover {
      background: var(--hover-bg);
    }

    .character-circle-form-actions {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
    }

    .character-circle-btn {
      height: 32px;
      padding: 0 14px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      color: var(--text-primary);
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s ease;
      white-space: nowrap;
    }

    .character-circle-btn.primary {
      background: var(--text-primary);
      color: var(--bg-primary);
      border-color: var(--text-primary);
    }

    .character-circle-btn.secondary:hover,
    .character-circle-btn.primary:hover {
      transform: translateY(-1px);
    }

    .character-circle-btn:active {
      transform: scale(0.98);
    }

    .character-circle-chip-row {
      display: flex;
      gap: 8px;
      overflow-x: auto;
      padding-bottom: 2px;
      scrollbar-width: none;
    }

    .character-circle-chip-row::-webkit-scrollbar {
      display: none;
    }

    .character-circle-chip {
      padding: 6px 12px;
      border-radius: 999px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      font-size: 11px;
      color: var(--text-secondary);
      white-space: nowrap;
      transition: all 0.2s ease;
    }

    .character-circle-chip.active {
      background: var(--text-primary);
      color: var(--bg-primary);
      border-color: var(--text-primary);
    }

    .character-circle-member-toolbar {
      display: flex;
      align-items: flex-end;
      gap: 8px;
      flex-wrap: wrap;
    }

    .character-circle-select {
      flex: 1 1 180px;
      display: flex;
      flex-direction: column;
      gap: 4px;
      min-width: 160px;
    }

    .character-circle-select-input {
      width: 100%;
      padding: 8px 10px;
      border-radius: 10px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      color: var(--text-primary);
      font-size: 12px;
      outline: none;
    }

    .character-circle-member-list {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .character-circle-member-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 8px;
      border-radius: 12px;
      background: var(--bg-primary);
      border: 1px solid var(--border-color);
    }

    .character-circle-member-left {
      display: flex;
      align-items: center;
      gap: 8px;
      min-width: 0;
    }

    .character-circle-avatar {
      width: 32px;
      height: 32px;
      border-radius: 10px;
      background: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      flex-shrink: 0;
    }

    .character-circle-avatar img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .character-circle-avatar svg {
      width: 16px;
      height: 16px;
      stroke: var(--text-secondary);
      fill: none;
      stroke-width: 1.8;
    }

    .character-circle-member-name {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-primary);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .character-circle-member-meta {
      font-size: 10px;
      color: var(--text-tertiary);
    }

    .character-circle-remove-btn {
      width: 30px;
      height: 30px;
      border-radius: 10px;
      background: var(--bg-secondary);
      border: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.2s ease;
      flex-shrink: 0;
    }

    .character-circle-remove-btn:hover {
      background: var(--hover-bg);
    }

    .character-circle-remove-btn svg {
      width: 14px;
      height: 14px;
      stroke: var(--text-primary);
      fill: none;
      stroke-width: 2;
    }

    .character-circle-relation-form {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .character-circle-relation-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }

    .character-circle-relation-list {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .character-circle-relation-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 8px 10px;
      border-radius: 12px;
      background: var(--bg-primary);
      border: 1px solid var(--border-color);
    }

    .character-circle-relation-left {
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 0;
    }

    .character-circle-relation-name {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-primary);
    }

    .character-circle-relation-note {
      font-size: 10px;
      color: var(--text-tertiary);
    }

    .character-circle-empty {
      font-size: 12px;
      color: var(--text-tertiary);
      padding: 8px 2px;
    }

    /* 导入后刷新动画 */
    @keyframes characterGridRefresh {
      0% { opacity: 0.6; transform: translateY(8px); }
      100% { opacity: 1; transform: translateY(0); }
    }

    .character-grid.refreshing {
      animation: characterGridRefresh 0.55s ease both;
    }

    /* Character Detail Modal */
    .character-modal {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.8);
      backdrop-filter: blur(8px);
      z-index: 10000;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
      animation: fadeIn 0.3s ease;
    }

    .character-modal.active {
      display: flex;
    }

    .character-modal.closing {
      animation: fadeOut 0.3s ease;
    }

    .character-modal.closing .id-card {
      animation: modalSlideOut 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    /* ID Card Container */
    .id-card {
      width: 100%;
      max-width: 380px;
      background: var(--bg-primary);
      border-radius: 24px;
      position: relative;
      overflow: hidden;
      animation: modalSlideIn 0.4s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
      max-height: 90vh;
      overflow-y: auto;
      scrollbar-width: thin;
    }

    .id-card::-webkit-scrollbar {
      width: 6px;
    }

    .id-card::-webkit-scrollbar-track {
      background: transparent;
    }

    .id-card::-webkit-scrollbar-thumb {
      background: var(--border-color);
      border-radius: 3px;
    }

    /* ID Card Header */
    .id-card-header {
      background: var(--accent-color);
      color: var(--bg-primary);
      padding: 16px 20px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      position: sticky;
      top: 0;
      z-index: 1;
    }

    .id-card-header::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 4px;
      background: repeating-linear-gradient(
        90deg,
        var(--bg-primary) 0px,
        var(--bg-primary) 4px,
        transparent 4px,
        transparent 8px
      );
    }

    .id-card-title {
      font-size: 11px;
      font-family: 'JetBrains Mono', monospace;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      opacity: 0.9;
    }

    .id-card-number {
      font-size: 13px;
      font-family: 'JetBrains Mono', monospace;
      font-weight: 600;
      letter-spacing: 0.05em;
    }

    .id-card-close {
      position: absolute;
      top: -40px;
      right: 0;
      width: 32px;
      height: 32px;
      background: var(--bg-primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.2s ease;
      z-index: 2;
    }

    .id-card-close:hover {
      transform: scale(1.1) rotate(90deg);
      background: var(--accent-color);
    }

    .id-card-close svg {
      width: 16px;
      height: 16px;
      stroke: var(--text-primary);
      fill: none;
      stroke-width: 2;
    }

    .id-card-close:hover svg {
      stroke: var(--bg-primary);
    }

    /* ID Card Body */
    .id-card-body {
      padding: 24px 20px;
    }

    /* Profile Section */
    .id-profile {
      display: flex;
      gap: 16px;
      margin-bottom: 24px;
      padding-bottom: 24px;
      border-bottom: 2px dashed var(--border-color);
      position: relative;
    }

    .id-profile::after {
      content: '';
      position: absolute;
      bottom: -6px;
      left: 50%;
      transform: translateX(-50%);
      width: 40px;
      height: 4px;
      background: var(--accent-color);
      opacity: 0.2;
    }

    .id-avatar-large {
      width: 100px;
      height: 120px;
      background: var(--bg-tertiary);
      border: 2px solid var(--border-color);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      position: relative;
      overflow: hidden;
    }

    .id-avatar-large svg {
      width: 50%;
      height: 50%;
      stroke: var(--text-tertiary);
      fill: none;
      stroke-width: 1.5;
    }

    .id-avatar-large img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .id-avatar-large::after {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 40%;
      background: linear-gradient(to top, var(--bg-tertiary), transparent);
    }

    /* Barcode */
    .id-barcode {
      position: absolute;
      bottom: 4px;
      left: 50%;
      transform: translateX(-50%);
      display: flex;
      gap: 1px;
      height: 24px;
      opacity: 0.4;
      z-index: 1;
    }

    .barcode-line {
      width: 2px;
      background: var(--text-primary);
      height: 100%;
    }

    .barcode-line:nth-child(odd) {
      height: 80%;
    }

    .barcode-line:nth-child(3n) {
      height: 60%;
    }

    .id-info-main {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .id-name {
      font-size: 18px;
      font-weight: 700;
      color: var(--text-primary);
      line-height: 1.2;
      margin-bottom: 4px;
      font-family: 'Noto Sans JP', sans-serif;
    }

    .id-role {
      font-size: 12px;
      color: var(--text-secondary);
      font-family: 'JetBrains Mono', monospace;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      background: var(--bg-tertiary);
      padding: 4px 8px;
      border-radius: 6px;
      display: inline-block;
      align-self: flex-start;
    }

    .id-meta-grid {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 6px 12px;
      margin-top: auto;
      font-size: 11px;
    }

    .id-meta-label {
      color: var(--text-tertiary);
      font-family: 'JetBrains Mono', monospace;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .id-meta-value {
      color: var(--text-primary);
      font-weight: 500;
    }

    /* Bio Section */
    .id-section {
      margin-bottom: 20px;
    }

    .id-section:last-child {
      margin-bottom: 0;
    }

    .id-section-header {
      font-size: 10px;
      font-family: 'JetBrains Mono', monospace;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--text-tertiary);
      margin-bottom: 8px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .id-section-header::before {
      content: '';
      width: 12px;
      height: 2px;
      background: var(--accent-color);
      opacity: 0.3;
    }

    .id-bio-text {
      font-size: 13px;
      line-height: 1.6;
      color: var(--text-secondary);
      background: var(--bg-tertiary);
      padding: 12px;
      border-radius: 12px;
      border: 1px solid var(--border-color);
      font-family: 'Noto Sans JP', sans-serif;
      max-height: 150px;
      overflow-y: auto;
      scrollbar-width: thin;
      scrollbar-color: var(--border-color) transparent;
    }

    .id-bio-text::-webkit-scrollbar {
      width: 6px;
    }

    .id-bio-text::-webkit-scrollbar-track {
      background: transparent;
    }

    .id-bio-text::-webkit-scrollbar-thumb {
      background: var(--border-color);
      border-radius: 3px;
    }

    /* Action Buttons */
    .char-action-btn {
      padding: 6px 12px;
      border-radius: 8px;
      border: 1px solid var(--border-color);
      background: var(--bg-primary);
      color: var(--text-secondary);
      font-size: 11px;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.2s ease;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
    }

    .char-action-btn:hover {
      background: var(--bg-tertiary);
      transform: scale(1.02);
    }

    .char-action-btn:active {
      transform: scale(0.98);
    }

    .char-action-btn.primary {
      color: var(--accent-color);
      border-color: var(--accent-color);
    }

    .char-action-btn.primary:hover {
      background: var(--accent-color);
      color: var(--bg-primary);
    }

    .char-action-btn.danger {
      color: #ef4444;
      border-color: #ef4444;
    }

    .char-action-btn.danger:hover {
      background: #ef4444;
      color: white;
    }

    /* ID Card Footer */
    .id-card-footer {
      background: var(--bg-tertiary);
      padding: 12px 20px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-top: 1px solid var(--border-color);
      position: sticky;
      bottom: 0;
    }

    .id-watermark {
      font-size: 9px;
      color: var(--text-tertiary);
      font-family: 'JetBrains Mono', monospace;
      letter-spacing: 0.05em;
    }

    .id-status-badge {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 10px;
      color: var(--text-secondary);
      font-weight: 500;
    }

    .id-status-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #22c55e;
      box-shadow: 0 0 8px rgba(34, 197, 94, 0.5);
      animation: pulse 2s infinite;
    }

    /* Corner Decorations */
    .corner-decoration {
      position: absolute;
      width: 40px;
      height: 40px;
      opacity: 0.1;
      pointer-events: none;
    }

    .corner-decoration.top-left {
      top: 0;
      left: 0;
      border-top: 3px solid var(--accent-color);
      border-left: 3px solid var(--accent-color);
      border-top-left-radius: 24px;
    }

    .corner-decoration.bottom-right {
      bottom: 0;
      right: 0;
      border-bottom: 3px solid var(--accent-color);
      border-right: 3px solid var(--accent-color);
      border-bottom-right-radius: 24px;
    }

    /* Modal Animations */
    @keyframes modalSlideIn {
      from {
        opacity: 0;
        transform: scale(0.9) translateY(20px);
      }
      to {
        opacity: 1;
        transform: scale(1) translateY(0);
      }
    }

    @keyframes modalSlideOut {
      from {
        opacity: 1;
        transform: scale(1) translateY(0);
      }
      to {
        opacity: 0;
        transform: scale(0.9) translateY(20px);
      }
    }

    /* Character Edit/Create Modal */
    .character-edit-modal {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.85);
      backdrop-filter: blur(10px);
      z-index: 10001;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
      animation: fadeIn 0.3s ease;
    }

    .character-edit-modal.active {
      display: flex;
    }

    .character-edit-modal.closing {
      animation: fadeOut 0.3s ease;
    }

    .character-edit-modal.closing .edit-card {
      animation: modalSlideOut 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    /* Edit Card */
    .edit-card {
      width: 100%;
      max-width: 420px;
      background: var(--bg-primary);
      border-radius: 24px;
      overflow: hidden;
      animation: modalSlideIn 0.4s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
      max-height: 90vh;
      display: flex;
      flex-direction: column;
    }

    /* Edit Card Header */
    .edit-card-header {
      background: var(--accent-color);
      color: var(--bg-primary);
      padding: 20px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-shrink: 0;
    }

    .edit-card-title {
      font-size: 16px;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .edit-card-close {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.2);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .edit-card-close:hover {
      background: rgba(255, 255, 255, 0.3);
      transform: rotate(90deg);
    }

    .edit-card-close svg {
      width: 16px;
      height: 16px;
      stroke: var(--bg-primary);
      fill: none;
      stroke-width: 2;
    }

    /* Edit Card Body */
    .edit-card-body {
      padding: 24px;
      overflow-y: auto;
      flex: 1;
      scrollbar-width: thin;
      scrollbar-color: var(--border-color) transparent;
    }

    .edit-card-body::-webkit-scrollbar {
      width: 6px;
    }

    .edit-card-body::-webkit-scrollbar-track {
      background: transparent;
    }

    .edit-card-body::-webkit-scrollbar-thumb {
      background: var(--border-color);
      border-radius: 3px;
    }

    /* Edit Section */
