    }

    #momentsScreen .moments-empty-body {
      display: grid;
      grid-template-columns: 72px 1fr;
      gap: 14px;
      align-items: center;
    }

    #momentsScreen .moments-empty-film {
      position: relative;
      width: 64px;
      height: 96px;
      border: 1px solid var(--moments-cine-border-2);
      background: repeating-linear-gradient(
        180deg,
        rgba(0, 0, 0, 0.08),
        rgba(0, 0, 0, 0.08) 6px,
        transparent 6px,
        transparent 12px
      );
