    [data-theme='dark'] #momentsScreen .moments-empty-film {
      background: repeating-linear-gradient(
        180deg,
        rgba(255, 255, 255, 0.08),
        rgba(255, 255, 255, 0.08) 6px,
        transparent 6px,
        transparent 12px
