    /* Cassette Card */
    @keyframes momentsSpin {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

    #momentsScreen .moments-cine-cassette {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 12px;
      border-radius: 14px;
      background: #ffffff;
      color: #000000;
      box-shadow: 0 10px 22px rgba(0, 0, 0, 0.14);
      transform: translateY(0);
      transition: transform 0.25s ease;
    }

    [data-theme='dark'] #momentsScreen .moments-cine-cassette {
      background: #e5e5e5;
    }

    #momentsScreen .moments-cine-cassette:hover {
      transform: translateY(-2px);
    }

    #momentsScreen .moments-cine-cassette-icon {
      width: 48px;
      height: 48px;
      background: #000000;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
      flex-shrink: 0;
    }

    #momentsScreen .moments-cine-reel {
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: #ffffff;
      animation: momentsSpin 3s linear infinite;
    }

    #momentsScreen .moments-cine-reel-left {
      margin-right: 12px;
    }

    #momentsScreen .moments-cine-cassette-line {
      position: absolute;
      left: 0;
      right: 0;
      top: 50%;
      height: 1px;
      background: rgba(255, 255, 255, 0.20);
