      justify-content: flex-start;
      overflow: hidden;
    }

    .style-preview-content > div {
      width: 100%;
      height: 100%;
      box-sizing: border-box;
    }

    .style-preview-card[data-style="starline"] .style-preview-content > div {
      max-width: 100%;
      max-height: 100%;
      overflow: hidden;
