    /* ==========================================
     * STARLINE CHAT STYLE - 星轨异形风格
     * 完整搬运自 星轨.html（已移除 Dock）
     * ========================================== */

    .chat-style-starline .layout-starline {
      /* 日间模式变量 */
      --bg-primary: #ffffff;
      --bg-secondary: #f6f6f6;
      --bg-tertiary: #efefef;
      --text-primary: #111111;
      --text-secondary: #7a7a7a;
      --text-tertiary: #9a9a9a;
      --border-color: #e3e3e3;
      --accent-color: #111111;
      --shadow-sm: 0 2px 6px rgba(0, 0, 0, 0.08);
      --shadow-md: 0 10px 30px rgba(0, 0, 0, 0.12);
      --glass: rgba(255, 255, 255, 0.85);
      --star: #111111;
      --card-bg: #ffffff;
      --card-active: #f9f9f9;
    }

    [data-theme="dark"] .chat-style-starline .layout-starline {
      /* 夜间模式变量 */
      --bg-primary: #0b0b0b;
      --bg-secondary: #121212;
      --bg-tertiary: #1a1a1a;
      --text-primary: #f2f2f2;
      --text-secondary: #8c8c8c;
      --text-tertiary: #666666;
      --border-color: #2a2a2a;
      --accent-color: #f2f2f2;
      --shadow-sm: 0 2px 6px rgba(0, 0, 0, 0.4);
      --shadow-md: 0 12px 36px rgba(0, 0, 0, 0.6);
      --glass: rgba(20, 20, 20, 0.85);
      --star: #f2f2f2;
      --card-bg: #0b0b0b;
      --card-active: #151515;
    }

    .chat-style-starline .layout-starline * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      -webkit-tap-highlight-color: transparent;
      outline: none;
    }

    .chat-style-starline .layout-starline {
      width: 100%;
      height: 100%;
      overflow: hidden; /* 页面级禁止滚动，内容级允许滚动 */
    }

    .chat-style-starline .layout-starline {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-primary);
      color: var(--text-primary);
      transition: background 0.4s ease, color 0.4s ease;
    }

    /* 
       ===========================
       布局结构：星轨异形 (Starline)
       ===========================
    */
    .chat-style-starline .layout-starline {
      display: grid;
      grid-template-columns: 74px 1fr; /* 左侧星轨固定，右侧自适应 */
      grid-template-rows: auto auto 1fr; /* 顶部标题、工具栏、列表区域 */
      width: 100%;
      height: 100%;
      background: var(--bg-primary);
      animation: starlineIn 0.6s ease;
