    /* 左侧：星轨导航区 */
.chat-style-starline .star-rail {
  grid-row: 1 / span 3;
  padding: var(--app-header-total-padding) 10px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  border-right: 1px solid var(--border-color);
      position: relative;
      z-index: 2;
      background: var(--bg-primary);
      transition: border-color 0.4s ease, background 0.4s ease;
    }

    /* 贯穿上下的星轨线 */
    .chat-style-starline .star-rail::after {
      content: '';
      position: absolute;
      top: 88px;
      bottom: 120px;
      width: 1px;
      background: linear-gradient(180deg, transparent, var(--border-color), transparent);
    }

    /* 头像（点击切换主题） */
    .chat-style-starline .rail-avatar {
      width: 46px;
      height: 46px;
      border-radius: 14px;
      background: var(--bg-tertiary);
      border: 1px solid var(--border-color);
      position: relative;
      overflow: hidden;
      flex-shrink: 0;
      cursor: pointer;
      z-index: 5;
    }

    .chat-style-starline .rail-avatar img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0.8;
    }

    /* 头像外圈旋转星轨 */
    .chat-style-starline .rail-avatar::after {
      content: '';
      position: absolute;
      inset: -6px;
      border-radius: 50%;
      border: 1px dashed var(--border-color);
      animation: orbitSpin 10s linear infinite;
      opacity: 0.6;
      pointer-events: none;
    }

    .chat-style-starline .rail-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--text-secondary);
      opacity: 0.7;
      flex-shrink: 0;
      transition: all 0.3s ease;
    }

    .chat-style-starline .rail-dot.active {
      background: var(--text-primary);
      box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.08);
      transform: scale(1.1);
    }

    /* 右侧：顶部标题栏 */
    .chat-style-starline .starline-top {
      grid-column: 2;
      padding: 24px 20px 10px 18px;
      display: flex;
      align-items: flex-end; /* 底部对齐 */
      justify-content: space-between;
      border-bottom: 1px solid var(--border-color);
      background: var(--bg-primary);
      transition: border-color 0.4s ease, background 0.4s ease;
    }

