    .chat-style-starline .starline-card-content {
      display: flex;
      flex-direction: column;
      justify-content: center;
      min-width: 0; /* 防止文本溢出撑开 */
    }

    .chat-style-starline .starline-card-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 4px;
