      overflow: hidden;
      text-overflow: ellipsis;
    }

    /* 动画定义 */
    @keyframes orbitSpin {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

    @keyframes starlineIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }
    
    /* 提示气泡 */
