}

.diary-entry-content.collapsible.collapsed {
  max-height: 360px;
  overflow: hidden;
}

.diary-entry-content.collapsible.collapsed::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
