/* ==================== 通话悬浮球 ==================== */

.call-floating-ball {
  position: fixed;
  right: 50px;
  bottom: 100px;
  width: 58px;
  height: 58px;
  cursor: pointer;
  z-index: 9999;
  opacity: 0;
  pointer-events: none;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  will-change: transform, opacity;
}

.call-floating-ball.hidden {
  opacity: 0;
  pointer-events: none;
  transform: scale(0.3) translateY(20px);
}

.call-floating-ball.show {
  opacity: 1;
  pointer-events: auto;
  transform: scale(1) translateY(0);
}

/* 头像容器 */
.call-floating-avatar {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--bg-primary);
  border: 3px solid var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  z-index: 2;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.call-floating-avatar svg {
  width: 32px;
  height: 32px;
  stroke: var(--text-secondary);
  fill: none;
  stroke-width: 1.5;
}

.call-floating-avatar img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 脉冲波纹 - 默认隐藏 */
.call-floating-pulse {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 2px solid var(--text-primary);
  opacity: 0;
  z-index: 1;
  animation: none;
  transition: opacity 0.3s ease;
}

/* 只有AI回复时才显示波纹提醒 */
.call-floating-ball.has-reply .call-floating-pulse {
  opacity: 0.6;
  animation: floatingPulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

.call-floating-ball.has-reply .call-floating-pulse:nth-child(3) {
  animation-delay: 1s;
}

@keyframes floatingPulse {
  0% {
    transform: translate(-50%, -50%) scale(1);
    opacity: 0.6;
  }
  100% {
    transform: translate(-50%, -50%) scale(1.6);
    opacity: 0;
  }
}

/* 点击效果 */
.call-floating-ball:active .call-floating-avatar {
  transform: scale(0.9);
  transition: transform 0.15s ease;
}

/* 收纳动画 - 从大到小 */
.phone-call-screen.minimizing {
  animation: callMinimize 0.35s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  will-change: transform, opacity;
}

@keyframes callMinimize {
  0% {
    opacity: 1;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(0.5);
    pointer-events: none;
  }
}

/* 展开动画 - 从小到大 */
.phone-call-screen.expanding {
  animation: callExpand 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  will-change: transform, opacity;
}

@keyframes callExpand {
  0% {
    opacity: 0;
    transform: scale(0.5);
  }
  70% {
    opacity: 1;
    transform: scale(1.03);
  }
  100% {
    opacity: 1;
    transform: scale(1);
    pointer-events: auto;
  }
}

/* 关闭动画 - 淡出下滑（用于空号/通话中等场景） */
.phone-call-screen.closing {
  animation: callClose 0.3s cubic-bezier(0.4, 0, 1, 1) forwards;
  will-change: transform, opacity;
}

@keyframes callClose {
  0% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  100% {
    opacity: 0;
    transform: translateY(20px) scale(0.95);
    pointer-events: none;
  }
}

/* ==================== End 通话悬浮球 ==================== */

