/* ========== 悬浮按钮组 FAB ========== */
.theme-editor-fab {
  display: none;
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  flex-direction: column;
  gap: 8px;
  z-index: 9999;
  transition: opacity 0.25s ease, transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.theme-editor-fab.active {
  display: flex;
}

/* 面板展开时隐藏FAB按钮 */
.theme-editor-fab.panel-open {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-50%) translateX(20px);
}

/* 双击页面：隐藏/显示 FAB（防遮挡） */
.theme-editor-fab.fab-hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateY(-50%) translateX(20px);
}

/* FAB 按钮基础样式 */
.theme-fab-btn {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid var(--border-color);
  background: var(--bg-primary);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.theme-fab-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-secondary);
  fill: none;
  stroke-width: 1.8;
}

.theme-fab-btn:active {
  transform: scale(0.92);
}

/* 面板按钮 */
.theme-fab-btn.panel {
  background: var(--bg-secondary);
}

.theme-fab-btn.panel.expanded {
  background: var(--text-primary);
  border-color: var(--text-primary);
}

.theme-fab-btn.panel.expanded svg {
  stroke: var(--bg-primary);
}

/* 取消按钮 */
.theme-fab-btn.cancel:hover {
  background: rgba(255, 59, 48, 0.1);
  border-color: rgba(255, 59, 48, 0.3);
}

.theme-fab-btn.cancel:hover svg {
  stroke: #ff3b30;
}

/* 保存按钮 */
.theme-fab-btn.save {
  background: var(--text-primary);
  border-color: var(--text-primary);
}

.theme-fab-btn.save svg {
  stroke: var(--bg-primary);
}

.theme-fab-btn.save:hover {
  opacity: 0.9;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.2);
}

/* ========== 面板背景遮罩 ========== */
.theme-editor-backdrop {
  display: none;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.3);
  z-index: 9997;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.theme-editor-backdrop.active {
  display: block;
  opacity: 1;
}

/* ========== 底部编辑面板容器 ========== */
.theme-editor-panel-container {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 9998;
  transform: translateY(100%);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
}

.theme-editor-panel-container.expanded {
  transform: translateY(0);
  pointer-events: auto;
}

/* 底部编辑面板 */
.theme-editor-panel {
  display: flex;
  flex-direction: column;
  background: var(--bg-primary);
  border-radius: 24px 24px 0 0;
  overflow: hidden;
  box-shadow: 0 -4px 30px rgba(0, 0, 0, 0.15);
