  opacity: 0.5;
}

/* 标签页 - 胶囊按钮样式 */
.theme-editor-tabs {
  display: flex;
  padding: 8px 14px 12px;
  gap: 6px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--border-color);
}

.theme-editor-tab {
