}

.theme-editor-toggle-hint {
  font-size: 10px;
  color: var(--text-tertiary);
}

/* 编辑区块 */
.theme-editor-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.theme-editor-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* 分类标题 - 胶囊标签样式 */
.theme-editor-section-header > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
