  height: 14px;
  stroke: var(--text-secondary);
  fill: none;
  stroke-width: 2;
}

.theme-editor-action-btn:hover {
  background: var(--text-primary);
}

.theme-editor-action-btn:hover svg {
  stroke: var(--bg-primary);
}

/* 预设主题列表 */
.theme-editor-preset-list {
