  fill: none;
  stroke-width: 1.5;
  margin-bottom: 6px;
  opacity: 0.6;
}

.theme-editor-preset-empty > span {
  font-size: 12px;
  color: var(--text-secondary);
}

.theme-editor-preset-empty-hint {
  font-size: 10px;
  color: var(--text-tertiary);
  margin-top: 3px;
}

/* CSS编辑区 */
.theme-editor-css-hint {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 10px;
  color: var(--text-tertiary);
}

.theme-editor-css-hint svg {
  width: 12px;
  height: 12px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  flex-shrink: 0;
  opacity: 0.7;
}

.theme-editor-css-textarea {
  width: 100%;
  min-height: 130px;
  padding: 12px;
