/* ==================== Chat Add Contact Overlay ==================== */
.chat-add-contact-overlay {
  position: absolute;
  inset: 0;
  z-index: 1200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(10px);
