.chat-add-contact-star::before,
.chat-add-contact-star::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 10px;
  height: 2px;
  background: var(--text-tertiary);
  transform: translate(-50%, -50%);
}

.chat-add-contact-star::after {
