}

.chat-add-contact-star.tiny {
  width: 6px;
  height: 6px;
  opacity: 0.35;
}

.chat-add-contact-star.tiny::before,
.chat-add-contact-star.tiny::after {
  width: 6px;
}

.chat-add-contact-panel {
