  --text-secondary: #888888;
  --line-color: rgba(255, 255, 255, 0.6);
  --line-faint: rgba(255, 255, 255, 0.15);
  --accent-shape: #ffffff;
  --node-bg: #000000;
  --shadow: 0 4px 20px rgba(255,255,255,0.05);
