}

#chatScreen.chat-style-poetry .chat-poetry-style-view .chapter-link {
  font-family: 'Syncopate', sans-serif;
  font-size: 10px;
  letter-spacing: 2px;
  text-transform: uppercase;
  border-bottom: 1px solid var(--text-primary);
  padding-bottom: 2px;
