}

#chatScreen.chat-style-poetry .chat-poetry-style-view .theme-switch {
  width: 30px;
  height: 30px;
  border: 1px solid var(--text-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
