  --star-color: #333;
  --font-family: 'Helvetica Neue', Helvetica, sans-serif;
}

[data-theme='dark'] #userPlaylistView {
  --bg-color: #050505;
  --text-color: #ffffff;
  --line-color: rgba(255, 255, 255, 0.2);
  --pin-color: #ffffff;
  --secondary-text: #888888;
  --star-color: #fff;
}

#userPlaylistView,
#userPlaylistView * {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

.user-playlist-view {
