  overflow: hidden;
  transform: translateX(100%);
  opacity: 0;
  pointer-events: none;
  z-index: 12000;
}

.user-playlist-view.active {
  transform: translateX(0);
  opacity: 1;
  pointer-events: auto;
}

/* --- 1. 流动的背景诗篇 (保持原样) --- */
#userPlaylistView .poem-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
